import {request as r,conversation,continuation,journey} from './workspace-thread-content.js';
const b=(action,label,value='',disabled=false)=>`<button data-ws="${action}"${value?` data-value="${value}"`:''}${disabled?' disabled':''}>${label}</button>`;
const list=items=>`<ul>${items.map(x=>`<li>${x}</li>`).join('')}</ul>`;
const product=(name,body,extra='')=>`<div class="wt-product ${extra}"><div class="wt-product-bar"><b>${name}</b><span>Demonstration</span></div>${body}</div>`;
const trace=s=>`<div class="wt-trace" aria-label="Context carried with this request">${s.thread.conversation?conversation.slice(0,s.thread.conversation).map(x=>`<span>${x[2]}</span>`).join(''):'<span>Discuss the migration plan next week</span>'}${s.thread.threadDone?'<span class="wt-unresolved">1 OPEN QUESTION · downtime approval</span>':''}</div>`;
function opening(s){return `<div class="wt-opening"><small>08:03 · CUSTOMER</small><blockquote>“${r.body}”</blockquote><p>ONE REQUEST.</p>${s.thread.opening?'<h2>WATCH WHAT HAPPENS TO IT.</h2>':''}<button class="wt-compare" data-ws="next">Compare the fragmented workday</button></div>`;}
function mail(){return product('Gmail',`<div class="wt-mail"><div class="wt-mail-head"><span class="wt-person">C</span><div><b>Customer</b><small>to Dias · 08:03</small></div><span>Inbox</span></div><p class="wt-letter">${r.body}</p><div class="wt-inline">${b('next','FIND A TIME →')}<span>Carry the subject and people into an event.</span></div></div>`);}
function calendar(s){return product('Google Calendar',`<div class="wt-scheduler"><section><small>08:07 · FROM THE CUSTOMER REQUEST</small><div class="wt-event-field"><b>People</b><span>Customer · ${s.event?'response pending':'to invite'}<br>Dias / AE${s.team?' · Presales':''}</span>${b('invite',s.team?'Team added':'INVITE TEAM','',s.team)}</div><div class="wt-event-field"><b>Time</b><span>${s.slot||'Choose a proposed time'}</span>${b('find-time','FIND A TIME','',s.availability)}</div><div class="wt-event-field"><b>Join</b><span>${s.meetLink?'Google Meet attached':'Meeting access'}</span>${b('meet-link',s.meetLink?'Meet added':'ADD GOOGLE MEET','',s.meetLink)}</div><div class="wt-event-field"><b>Prepare</b><span>${s.attachment?'Assessment.xlsx · access reviewed':'Related assessment'}</span>${b('attach',s.attachment?'File attached':'ATTACH FILE','',s.attachment)}</div>${s.event?'<p class="wt-small-reveal">The request now has<br><strong>a time. People. A place to continue.</strong></p>':b('create-event','CREATE EVENT →','',!(s.slot&&s.team&&s.meetLink&&s.attachment))}</section><section class="wt-times"><small>NEXT WEEK · EXAMPLE AVAILABILITY</small>${s.availability?`<div class="wt-time-heading"><span>Time</span><span>AE / Presales</span><span>Customer</span></div>${['Tue 09:00','Tue 10:30','Wed 14:00'].map((slot,i)=>`<button data-ws="slot" data-value="${slot}" class="${s.slot===slot?'selected':''}" ${i===0?'disabled title="The internal team has a conflict at this time."':''}><b>${slot}</b><span>${i?'Available':'Conflict'}</span><span>Confirm</span></button>`).join('')}<p>Shared internal availability. Customer availability and invitation acceptance still need confirmation.</p>`:'<div class="wt-time-grid"><span>09:00</span><i></i><span>10:00</span><i></i><span>11:00</span><i></i></div><p>Find a time to compare the team’s shared availability.</p>'}</section></div>`);}
const notes=()=>`<div class="wt-notes"><small>MEETING NOTES · SIMULATED CONTENT</small><h3>What continues after the call</h3><p>Customer is evaluating migration of an existing on-prem workload.</p><b>DIRECTION</b><p>${r.direction}</p><b>OPEN QUESTIONS</b><p>${r.open.slice(0,3).join(' · ')}</p><b>ACTIONS</b>${list(r.actions)}</div>`;
function meet(s){const t=s.thread;if(t.end)return `<div class="wt-freeze"><div class="wt-retained"><small>CONTEXT REMAINS</small><p>On-prem workload · Assessment first</p><p>Dependencies unknown · Downtime approval open</p><span>Datalabs prepares scope · Customer confirms owner</span></div><h2>The meeting ended.${t.end===2?"<em>But the work didn’t.</em>":''}</h2></div>`;
return product('Google Meet',`<div class="wt-meeting"><small>${s.slot} · NEXT WEEK · CONFIRMED FOR THIS EXAMPLE</small><div class="wt-participants">${r.people.map((name,i)=>`<div class="${s.meetingStarted&&conversation[Math.max(0,t.conversation-1)][0]===(i===0?'Customer':i===2?'Presales':'Dias')?'speaking':''}"><span>${['C','D','P'][i]}</span><b>${name}</b></div>`).join('')}</div>${s.meetingStarted?`<div class="wt-dialogue">${t.conversation?`<small>${conversation[t.conversation-1][0]}</small><blockquote>“${conversation[t.conversation-1][1]}”</blockquote>`:'<p>The customer request is now a conversation.</p>'}</div>`:'<p>The event brought the same people and preparation into the meeting.</p>'}<div class="wt-meet-controls">${!s.meetingStarted?b('start-meet','START THE MEETING →'):t.conversation<4?b('conversation','CONTINUE THE CONVERSATION →'):!s.notes?b('notes','TAKE NOTES →'):b('end-meeting','END THE MEETING →')}</div>${s.notes?notes():''}<p class="wt-caveat">Note assistance is simulated. Eligible plan and applicable settings required; review the output and provide participant notice.</p></div>`);}
function space(s){const t=s.thread;let body='';if(!s.space||s.channel==='chat')body=`<div class="wt-chat"><small>Dias → Presales · direct conversation</small><p>Can you send the latest migration notes?</p><p class="wt-response">Here’s the link. Let’s keep the continuing project work together.</p><div class="wt-inline">${b('chat','USE CHAT')}${b('space','CREATE A SPACE →')}</div><p class="wt-caveat">A focused exchange. History still depends on settings.</p></div>`;else body=`<div class="wt-space-header"><small>SPACE</small><h3>${r.project}</h3><p>Dias / AE · Presales · Technical Team</p></div><div class="wt-space-layout ${t.threadOpen?'thread-open':''}"><div class="wt-space-main"><div class="wt-linked-context"><b>Selected meeting context</b><span>${r.direction}</span><span>Meeting Notes · Assessment.xlsx</span></div><div class="wt-message"><span class="wt-person">M</span><div><b>Maya</b><p>Customer confirmed downtime tolerance needs internal approval.</p>${b('thread-open',t.threadDone?'1 OPEN QUESTION · VIEW THREAD →':'REPLY IN THREAD →')}</div></div>${t.threadDone?`<div class="wt-shared-file"><small>SHARED WORK · FROM THIS DISCUSSION</small><b>${r.file}</b><span>Assessment preparation · access for the project team</span></div>`:''}<p class="wt-caveat">Context deliberately linked for this example. Space membership and file permissions are separate.</p></div>${t.threadOpen?`<aside class="wt-thread" aria-label="Replies to Maya’s downtime question"><div class="wt-thread-heading"><b>Thread · downtime approval</b>${b('thread-close','CLOSE THREAD')}</div><p class="wt-parent-quote">Maya · Downtime tolerance needs internal approval.</p>${t.replies>=1?'<p><b>Dias</b>Got it. I’ll keep this as an open item.</p>':''}${t.replies>=2?'<p><b>Presales</b>We’ll need this before finalizing the migration approach.</p><span class="wt-unresolved">1 OPEN QUESTION</span>':b('thread-reply',t.replies?'ADD PRESALES REPLY →':'ADD DIAS REPLY →')}</aside>`:''}</div>`;
return product('Google Chat',body)+`<p class="wt-context-caption">Chat for the conversation. A Space for the work that continues.</p>`;}
function documentBody(s){const n=s.thread.contributions;return `<article class="wt-document"><small>${r.project} / Shared working file</small><h3>${r.file}</h3><div class="wt-document-section"><b>CURRENT ENVIRONMENT</b><p>Known: on-prem workload</p><b>MIGRATION OBJECTIVE</b><p>Evaluate migration approach</p><b>KEY CONCERN</b><p>Downtime</p></div><div class="wt-document-section ${n>=1?'wt-edit-presales':''}"><b>OPEN QUESTIONS</b><p>${n>=1?'Application dependencies · Data volume · Approved downtime tolerance':'Waiting for assessment inputs'}</p>${n>=1?'<span class="wt-cursor">↖ Presales</span>':''}</div>${n>=2?'<div class="wt-document-section wt-edit-tech"><p>Workload owner: <b>Customer to confirm</b></p><span class="wt-cursor">↖ Technical Team</span></div>':''}<div class="wt-document-section ${n>=3?'wt-edit-ae':''}"><b>NEXT ACTION</b><p>${n>=3?'Prepare assessment scope after missing information is confirmed.':'Assessment preparation'}</p>${n>=3?'<span class="wt-cursor">↖ Dias / AE</span>':''}</div></article>`;}
function work(s){if(!s.file)return product('Google Drive',`<div class="wt-drive"><small>${r.project}</small><h3>Work from the conversation.</h3><button class="wt-file-row" data-ws="file" data-value="Proposal Draft"><b>${r.file}</b><span>Shared with project team</span><strong>OPEN DOCUMENT →</strong></button><p>Meeting Notes · Assessment.xlsx · Architecture.pdf</p></div>`);
return product('Google Docs',`<div class="wt-doc-toolbar"><span>Shared with the project team</span><div class="wt-presence"><span>Dias</span><span>Presales</span><span>Technical Team</span></div></div>${documentBody(s)}${s.thread.contributions<3?`<div class="wt-document-action">${b('contribute',['ADD PRESALES INPUT →','ADD TECHNICAL TEAM INPUT →','ADD NEXT ACTION →'][s.thread.contributions])}</div>`:'<p class="wt-context-caption">All contributions remain in this working document.</p>'}`);}
function gemini(s){return product('Google Docs',`<div class="wt-assistance"><div class="wt-source-document">${documentBody(s)}</div><aside class="wt-assistant"><div class="wt-assistant-title"><b>Gemini</b><small>SELECTED CONTEXT</small></div><div class="wt-references ${s.ai?'connected':''}">${['Request','Meeting','Thread','Document'].map((x,i)=>`<span style="--reference:${i}">${x}</span>`).join('')}</div><p class="wt-prompt">Summarize the migration requirements and identify the remaining open questions.</p>${s.ai?`<div class="wt-answer"><small>SIMULATED CONTENT</small><h4>MIGRATION REQUIREMENTS</h4>${list(r.known)}<h4>OPEN QUESTIONS</h4>${list(r.open)}<h4>NEXT PREPARATION</h4><p>Prepare assessment scope after the missing information is confirmed.</p></div>`:b('ai','SUMMARIZE SELECTED CONTEXT →')}<p class="wt-caveat">Conceptual source selection, not live AI. Capabilities depend on plan, permissions and settings. Review against the source material.</p></aside></div>`);}
function followup(s){return product('Gmail',`<div class="wt-mail"><div class="wt-mail-head"><span class="wt-person">C</span><div><b>Customer</b><small>${r.body}</small></div></div>${s.draft?`<div class="wt-compose"><div><b>RE: ${r.subject}</b><small>Draft · not sent · SIMULATED CONTENT</small></div><p>Hi Customer,</p><p>Thank you for the discussion today. The next step is assessment preparation for your current workload, dependencies and migration constraints.</p><p>Before that, please confirm application dependencies, data volume and downtime tolerance, and identify the workload owner.</p><p>We’ll use these inputs to prepare the next discussion.</p><p>Regards,<br>Dias</p><small>Review the draft. Nothing is sent from this demonstration.</small></div>`:`<div class="wt-reply-context"><p>The reply starts with the context the team has already built.</p>${b('draft','CREATE FOLLOW-UP →')}</div>`}</div>`);}
function final(s){const t=s.thread;return `<div class="wt-finale"><ol class="wt-continuous-line" aria-label="One continuous work thread">${journey.map(([moment,app])=>`<li><span>${moment}</span><small>${app}</small></li>`).join('')}</ol>${t.finalBeat===0?'<h2>The request is still here.</h2>':t.finalBeat===1?'<h2>One request.<br>Many moments of work.<br><em>One continuous context.</em></h2>':'<h2>The tools changed.<br><em>The work didn’t have to start over.</em></h2>'}${t.discovery?`<div class="wt-discovery"><h3>How does work continue after a meeting in your organization?</h3><div>${continuation.map(x=>`<button data-ws="signal" data-value="${x}" aria-pressed="${t.signal===x}">${x}</button>`).join('')}</div>${t.signal?`<p>Let’s follow one handoff through ${t.signal.toLowerCase()}.</p>`:''}</div>`:''}</div>`;}
export function threadPrimary(s){const t=s.thread;if(s.scene==='opening')return t.opening?['start-thread','START THE WORKDAY →']:['opening-reveal','START THE WORKDAY →'];if(s.scene==='mail')return null;if(s.scene==='calendar')return ['next','CONTINUE TO THE MEETING →',!s.event];if(s.scene==='meet')return t.end?[ 'next',t.end===1?'REVEAL →':'FOLLOW THE THREAD →']:null;if(s.scene==='collaborate')return ['next','OPEN THE SHARED WORK →',!t.threadDone||s.channel!=='space'];if(s.scene==='work')return ['next','USE THE CONTEXT →',s.thread.contributions<3];if(s.scene==='gemini')return ['next','RETURN TO THE CUSTOMER →',!s.ai];if(s.scene==='followup')return ['next','FOLLOW THE WHOLE THREAD →',!s.draft];if(s.scene==='final')return t.finalBeat<2?['next','REVEAL →']:!t.discovery?['discovery','ASK ABOUT YOUR WORKFLOW →']:['reset','RESTART ↺'];return null;}
export function workspaceThreadShow(s){const t=s.thread;const primary=threadPrimary(s);const renderers={opening,mail,calendar,meet,collaborate:space,work,gemini,followup,final};const phase={opening:'REQUEST',mail:'REQUEST',calendar:'EVENT',meet:t.end?'DECISION':'CONVERSATION',collaborate:'THREAD',work:'SHARED WORK',gemini:'CONTEXT',followup:'RESPONSE',final:'ONE CONTINUOUS THREAD'}[s.scene];return `<section class="wt-stage wt-${s.scene} ${t.end&&s.scene==='meet'?'wt-is-frozen':''}" aria-label="Follow the thread" data-thread-scene="${s.scene}"><div class="wt-request-anchor" data-request-id="${r.id}"><span class="wt-request-marker" aria-hidden="true"></span><div><small>REQUEST #${r.id} <span> / ${phase}</span></small><h2>${r.subject}</h2></div><span class="wt-anchor-people">Customer · Dias · Presales</span></div>${s.scene==='opening'?'':trace(s)}<div class="ws-scene-body wt-scene-body" aria-live="polite">${renderers[s.scene](s)}</div><div class="wt-controls">${b('prev','← PREVIOUS','',s.scene==='opening')}<span>${primary?.[2]?'INTERACT · Complete this moment to continue.':''}</span>${primary?b(primary[0],primary[1],'',primary[2]):''}</div><div class="wt-demo-note">SIMULATED CONTENT · No messages or invitations are sent.</div></section>`;}
